import { useState, useRef, useEffect, useCallback } from 'react';
import { Play, Square, Shuffle, Trash2, Volume2, VolumeX } from 'lucide-react';
import { TRIGGERS, type DrumName } from './drums';

const STEPS = 16;

const TRACKS: { name: string; key: DrumName; color: string }[] = [
  { name: 'Kick', key: 'kick', color: '#fb7185' },
  { name: 'Snare', key: 'snare', color: '#fbbf24' },
  { name: 'Hi-Hat', key: 'hihat', color: '#34d399' },
  { name: 'Clap', key: 'clap', color: '#818cf8' },
  { name: 'Tom', key: 'tom', color: '#c084fc' },
];

type Pattern = boolean[][]; // [track][step]

const emptyPattern = (): Pattern => TRACKS.map(() => Array(STEPS).fill(false));

// (트랙별 켜진 스텝 인덱스)로 프리셋 패턴을 만든다.
const make = (
  kick: number[],
  snare: number[],
  hihat: number[],
  clap: number[],
  tom: number[],
): Pattern => {
  const p = emptyPattern();
  [kick, snare, hihat, clap, tom].forEach((arr, t) =>
    arr.forEach((s) => {
      p[t][s] = true;
    }),
  );
  return p;
};

const PRESETS: { name: string; pattern: Pattern }[] = [
  { name: '기본', pattern: make([0, 4, 8, 12], [4, 12], [0, 2, 4, 6, 8, 10, 12, 14], [], []) },
  { name: '하우스', pattern: make([0, 4, 8, 12], [4, 12], [2, 6, 10, 14], [4, 12], []) },
  { name: '힙합', pattern: make([0, 6, 10], [4, 12], [0, 2, 4, 6, 8, 10, 12, 14], [], [7, 15]) },
];

export default function App() {
  const [pattern, setPattern] = useState<Pattern>(PRESETS[0].pattern.map((r) => [...r]));
  const [bpm, setBpm] = useState(110);
  const [playing, setPlaying] = useState(false);
  const [step, setStep] = useState(-1);
  const [mutes, setMutes] = useState<boolean[]>(TRACKS.map(() => false));
  const [volumes, setVolumes] = useState<number[]>(TRACKS.map(() => 0.9));

  // 스케줄러가 항상 '최신' 상태를 읽도록 ref로 미러링(클로저 stale 방지).
  const ctxRef = useRef<AudioContext | null>(null);
  const patternRef = useRef(pattern);
  const mutesRef = useRef(mutes);
  const volumesRef = useRef(volumes);
  const bpmRef = useRef(bpm);
  patternRef.current = pattern;
  mutesRef.current = mutes;
  volumesRef.current = volumes;
  bpmRef.current = bpm;

  const nextStepRef = useRef(0);
  const nextTimeRef = useRef(0);
  const timerRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const queueRef = useRef<{ step: number; time: number }[]>([]);

  // 미리보기(lookahead) 스케줄러: 0.1초 앞의 박자까지 오디오 엔진에 예약해 둔다.
  const schedule = useCallback(() => {
    const ctx = ctxRef.current;
    if (!ctx) return;
    while (nextTimeRef.current < ctx.currentTime + 0.1) {
      const s = nextStepRef.current;
      const t = nextTimeRef.current;
      TRACKS.forEach((tr, ti) => {
        if (patternRef.current[ti][s] && !mutesRef.current[ti]) {
          TRIGGERS[tr.key](ctx, t, volumesRef.current[ti]);
        }
      });
      queueRef.current.push({ step: s, time: t });
      nextTimeRef.current += 60 / bpmRef.current / 4; // 16분음표 = 1박의 1/4
      nextStepRef.current = (s + 1) % STEPS;
    }
    timerRef.current = window.setTimeout(schedule, 25);
  }, []);

  // 재생 헤드(현재 칸) 표시는 오디오 시계 기준으로 그려 흔들림 없이 정확하게.
  const draw = useCallback(() => {
    const ctx = ctxRef.current;
    if (ctx) {
      while (queueRef.current.length && queueRef.current[0].time < ctx.currentTime) {
        setStep(queueRef.current.shift()!.step);
      }
    }
    rafRef.current = requestAnimationFrame(draw);
  }, []);

  const stop = useCallback(() => {
    if (timerRef.current) window.clearTimeout(timerRef.current);
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    timerRef.current = null;
    rafRef.current = null;
    queueRef.current = [];
    setPlaying(false);
    setStep(-1);
  }, []);

  const play = useCallback(() => {
    let ctx = ctxRef.current;
    if (!ctx) {
      ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      ctxRef.current = ctx;
    }
    ctx.resume(); // 브라우저 자동재생 정책: 사용자 클릭 시점에 켜야 소리가 난다.
    nextStepRef.current = 0;
    nextTimeRef.current = ctx.currentTime + 0.06;
    queueRef.current = [];
    setPlaying(true);
    schedule();
    rafRef.current = requestAnimationFrame(draw);
  }, [schedule, draw]);

  useEffect(() => () => stop(), [stop]); // 언마운트 시 정리

  const toggleCell = (t: number, s: number) =>
    setPattern((prev) => {
      const next = prev.map((row) => [...row]);
      next[t][s] = !next[t][s];
      return next;
    });

  const toggleMute = (t: number) =>
    setMutes((prev) => prev.map((m, i) => (i === t ? !m : m)));

  const setVolume = (t: number, v: number) =>
    setVolumes((prev) => prev.map((x, i) => (i === t ? v : x)));

  return (
    <div className="min-h-screen w-full flex items-center justify-center bg-gradient-to-b from-[#12141d] via-[#0c0e15] to-[#07080d] text-slate-100 p-4 sm:p-6 overflow-x-hidden">
      <div className="w-full max-w-[1080px]">
        <div className="rounded-[28px] border border-white/10 bg-[#151925]/90 shadow-2xl shadow-black/50 backdrop-blur px-5 py-6 sm:px-9 sm:py-8">
          {/* 헤더 + 트랜스포트 */}
          <header className="flex flex-wrap items-center gap-4 mb-7 sm:mb-9">
            <div className="flex items-center gap-3.5 mr-auto">
              <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-indigo-500 to-fuchsia-500 flex items-center justify-center shadow-lg shadow-indigo-500/30 shrink-0">
                <span className="text-2xl leading-none">🥁</span>
              </div>
              <div>
                <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight text-white leading-none">
                  Beat Maker
                </h1>
                <p className="text-sm text-slate-400 mt-2">드럼을 찍어 만드는 나만의 비트</p>
              </div>
            </div>

            {/* BPM */}
            <div className="flex items-center gap-3 h-12 px-4 rounded-2xl bg-white/5 border border-white/10">
              <span className="text-xs font-bold tracking-widest text-slate-400">BPM</span>
              <input
                type="range"
                min={60}
                max={180}
                value={bpm}
                onChange={(e) => setBpm(Number(e.target.value))}
                className="w-28 sm:w-40 accent-indigo-400 cursor-pointer"
              />
              <span className="text-lg font-bold font-mono text-white w-9 text-right tabular-nums">
                {bpm}
              </span>
            </div>

            {/* 재생 / 정지 */}
            <button
              onClick={playing ? stop : play}
              className={`flex items-center gap-2.5 h-12 px-7 rounded-2xl font-bold text-base transition-all active:scale-95 ${
                playing
                  ? 'bg-rose-500 hover:bg-rose-600 text-white shadow-lg shadow-rose-500/30'
                  : 'bg-indigo-500 hover:bg-indigo-600 text-white shadow-lg shadow-indigo-500/30'
              }`}
            >
              {playing ? <Square size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" />}
              {playing ? '정지' : '재생'}
            </button>
          </header>

          {/* 시퀀서 — 좁은 화면에선 이 영역만 가로 스크롤(페이지는 안 깨짐) */}
          <div className="overflow-x-auto -mx-1 px-1">
            <div className="min-w-[540px]">
              {/* 박자 눈금 (1·2·3·4) */}
              <div className="flex items-center mb-3 pl-[136px] sm:pl-[172px]">
                <div className="flex-1 grid grid-cols-4 gap-2.5 sm:gap-3">
                  {[1, 2, 3, 4].map((beat) => (
                    <div key={beat} className="text-xs font-bold tracking-widest text-slate-500">
                      {beat}
                    </div>
                  ))}
                </div>
              </div>

              {/* 트랙들 */}
              <div className="flex flex-col gap-2.5">
                {TRACKS.map((track, t) => (
                  <div key={track.key} className="flex items-center gap-3 sm:gap-4">
                    {/* 트랙 라벨 + 음소거 + 볼륨 */}
                    <div className="w-[124px] sm:w-[160px] shrink-0 flex items-center gap-2.5">
                      <span
                        className="w-3 h-3 rounded-full shrink-0"
                        style={{ backgroundColor: mutes[t] ? '#475569' : track.color }}
                      />
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-1.5">
                          <span
                            className={`text-[15px] font-bold truncate leading-tight ${
                              mutes[t] ? 'text-slate-600 line-through' : 'text-white'
                            }`}
                          >
                            {track.name}
                          </span>
                          <button
                            onClick={() => toggleMute(t)}
                            className="text-slate-500 hover:text-slate-200 transition-colors shrink-0"
                            title="음소거"
                          >
                            {mutes[t] ? <VolumeX size={16} /> : <Volume2 size={16} />}
                          </button>
                        </div>
                        <input
                          type="range"
                          min={0}
                          max={1}
                          step={0.01}
                          value={volumes[t]}
                          onChange={(e) => setVolume(t, Number(e.target.value))}
                          className="w-full h-1.5 mt-1.5 hidden sm:block cursor-pointer"
                          style={{ accentColor: track.color }}
                        />
                      </div>
                    </div>

                    {/* 16스텝 — 4칸씩 4그룹, aspect-square로 항상 정사각 패드 */}
                    <div className="flex-1 grid grid-cols-4 gap-2.5 sm:gap-3 min-w-0">
                      {[0, 1, 2, 3].map((group) => (
                        <div key={group} className="grid grid-cols-4 gap-1.5 min-w-0">
                          {[0, 1, 2, 3].map((i) => {
                            const s = group * 4 + i;
                            const on = pattern[t][s];
                            const isHead = s === step && playing;
                            return (
                              <button
                                key={s}
                                onClick={() => toggleCell(t, s)}
                                className={`aspect-square rounded-lg transition-all duration-100 ${
                                  isHead ? 'ring-2 ring-white scale-105' : 'hover:brightness-125'
                                }`}
                                style={{
                                  backgroundColor: on ? track.color : 'rgba(255,255,255,0.06)',
                                  boxShadow: on
                                    ? `0 0 16px ${track.color}80, inset 0 1px 0 rgba(255,255,255,0.25)`
                                    : 'inset 0 1px 0 rgba(255,255,255,0.04)',
                                }}
                                aria-label={`${track.name} step ${s + 1}`}
                              />
                            );
                          })}
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* 하단: 프리셋 / 랜덤 / 비우기 */}
          <div className="flex flex-wrap items-center gap-2.5 mt-7 sm:mt-9 pt-6 border-t border-white/10">
            <span className="text-xs font-bold tracking-widest text-slate-500 mr-1">프리셋</span>
            {PRESETS.map((p) => (
              <button
                key={p.name}
                onClick={() => setPattern(p.pattern.map((r) => [...r]))}
                className="h-10 px-4 rounded-xl bg-white/5 border border-white/10 text-sm font-semibold text-slate-300 hover:bg-white/10 hover:text-white transition-colors"
              >
                {p.name}
              </button>
            ))}
            <div className="flex-1" />
            <button
              onClick={() =>
                setPattern(TRACKS.map(() => Array.from({ length: STEPS }, () => Math.random() < 0.28)))
              }
              className="h-10 px-4 rounded-xl bg-white/5 border border-white/10 text-sm font-semibold text-slate-300 hover:text-white transition-colors flex items-center gap-2"
            >
              <Shuffle size={16} /> 랜덤
            </button>
            <button
              onClick={() => setPattern(emptyPattern())}
              className="h-10 px-4 rounded-xl bg-white/5 border border-white/10 text-sm font-semibold text-slate-400 hover:text-rose-300 hover:border-rose-400/30 transition-colors flex items-center gap-2"
            >
              <Trash2 size={16} /> 비우기
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

