// Web Audio API로 드럼 소리를 '합성'한다 — 외부 음원 파일 없이 오실레이터/노이즈로.
// 각 트리거는 (ctx, time, gain)을 받아 정확히 그 시각(time)에 한 번 소리를 낸다.
// time 을 받는 이유: 재생 스케줄러가 박자를 '미리' 예약해 타이밍이 흔들리지 않게 하기 위함.

export type DrumName = 'kick' | 'snare' | 'hihat' | 'clap' | 'tom';

// 짧게 솟았다가 사그라드는 음량 엔벌로프(공통). peak까지 튀고 decay초 동안 0으로 감쇠.
function envGain(ctx: AudioContext, time: number, peak: number, decay: number): GainNode {
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, time);
  g.gain.exponentialRampToValueAtTime(Math.max(peak, 0.0002), time + 0.002);
  g.gain.exponentialRampToValueAtTime(0.0001, time + decay);
  return g;
}

// 화이트 노이즈 버퍼(스네어/하이햇/클랩의 '치익' 성분).
function makeNoise(ctx: AudioContext): AudioBufferSourceNode {
  const len = Math.floor(ctx.sampleRate * 0.4);
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
  const src = ctx.createBufferSource();
  src.buffer = buf;
  return src;
}

function kick(ctx: AudioContext, time: number, gain: number): void {
  const osc = ctx.createOscillator();
  osc.frequency.setValueAtTime(150, time);
  osc.frequency.exponentialRampToValueAtTime(45, time + 0.18); // 피치를 떨어뜨려 '둥' 소리
  const g = envGain(ctx, time, gain, 0.4);
  osc.connect(g).connect(ctx.destination);
  osc.start(time);
  osc.stop(time + 0.4);
}

function snare(ctx: AudioContext, time: number, gain: number): void {
  const noise = makeNoise(ctx);
  const hp = ctx.createBiquadFilter();
  hp.type = 'highpass';
  hp.frequency.value = 1500;
  const ng = envGain(ctx, time, gain * 0.7, 0.2);
  noise.connect(hp).connect(ng).connect(ctx.destination);
  noise.start(time);
  noise.stop(time + 0.2);
  const osc = ctx.createOscillator();
  osc.type = 'triangle';
  osc.frequency.value = 180;
  const og = envGain(ctx, time, gain * 0.4, 0.1);
  osc.connect(og).connect(ctx.destination);
  osc.start(time);
  osc.stop(time + 0.1);
}

function hihat(ctx: AudioContext, time: number, gain: number): void {
  const noise = makeNoise(ctx);
  const hp = ctx.createBiquadFilter();
  hp.type = 'highpass';
  hp.frequency.value = 7000;
  const g = envGain(ctx, time, gain * 0.4, 0.05); // 아주 짧게 — 닫힌 하이햇
  noise.connect(hp).connect(g).connect(ctx.destination);
  noise.start(time);
  noise.stop(time + 0.06);
}

function clap(ctx: AudioContext, time: number, gain: number): void {
  // 여러 번의 짧은 노이즈 버스트를 겹쳐 박수 같은 질감을 만든다.
  for (const delay of [0, 0.01, 0.02]) {
    const noise = makeNoise(ctx);
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = 1200;
    const g = envGain(ctx, time + delay, gain * 0.5, 0.12);
    noise.connect(bp).connect(g).connect(ctx.destination);
    noise.start(time + delay);
    noise.stop(time + delay + 0.12);
  }
}

function tom(ctx: AudioContext, time: number, gain: number): void {
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(220, time);
  osc.frequency.exponentialRampToValueAtTime(90, time + 0.25);
  const g = envGain(ctx, time, gain, 0.3);
  osc.connect(g).connect(ctx.destination);
  osc.start(time);
  osc.stop(time + 0.3);
}

export const TRIGGERS: Record<DrumName, (ctx: AudioContext, time: number, gain: number) => void> = {
  kick,
  snare,
  hihat,
  clap,
  tom,
};
